cat > src/domain/FxQuote.java <<'E'
package domain;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A single quote returned by the FX vendor; {@code lagged} means a carried-over (~N) value. */
public record FxQuote(String pair, LocalDate date, BigDecimal rate, boolean lagged) {
    public FxQuote(String pair, LocalDate date, BigDecimal rate) {
        this(pair, date, rate, false);
    }
}
E
python3 -I - <<'E'
p='src/infra/FxqClient.java'
s=open(p).read()
s=s.replace('''    /** Parses one''','''    /** Raw stdout line for {@code fxq rate PAIR DATE --src 3} (settlement reference value). */
    public String settlementRate(String pair, LocalDate date) {
        List<String> cmd = new ArrayList<>();
        cmd.add(bin.toString());
        cmd.add("rate");
        cmd.add(pair);
        cmd.add(date.toString());
        cmd.add("--src");
        cmd.add("3");
        return run(cmd);
    }

    /** Parses one''')
s=s.replace("new BigDecimal(t[2]));","new BigDecimal(t[2]),\n                t.length > 3 && t[3].startsWith(\"~\"));")
open(p,'w').write(s)
p='src/service/RateService.java'
s=open(p).read()
s=s.replace('''        return quote(currency, date).rate();''','''        FxQuote q = quote(currency, date);
        if (!q.lagged()) return q.rate();
        String pair = CurrencyPairs.pairOf(currency);
        return settlementCache.computeIfAbsent(pair + "@" + date, k -> {
            vendorCalls++;
            return FxqClient.parse(client.settlementRate(pair, date)).rate();
        });''')
s=s.replace("    private int vendorCalls;","    private final Map<String, BigDecimal> settlementCache = new HashMap<>();\n    private int vendorCalls;")
open(p,'w').write(s)
E
bash test.sh 2>&1 | tail -15

